{
  "schemaVersion": "ride-output-v2.2.0",
  "label": {
    "text": "总距离 161.8 公里的长距离骑行",
    "conclusionType": "fact",
    "claimIds": ["claim:demo-ride-2026-07-22:v2:metric.distanceM"]
  },
  "overallAssessment": {
    "text": "本次骑行总距离 161.8 公里，移动时长 6 小时 40 分钟，累计爬升 2924 米，是一次高负荷的长距离骑行。",
    "conclusionType": "fact",
    "claimIds": [
      "claim:demo-ride-2026-07-22:v2:metric.distanceM",
      "claim:demo-ride-2026-07-22:v2:timing.movingDurationS",
      "claim:demo-ride-2026-07-22:v2:metric.elevationGainM"
    ]
  },
  "highlights": [
    {
      "text": "本次骑行包含 15 个爬坡段，其中最具挑战的爬坡段平均坡度 11.1%，平均功率 256W。",
      "conclusionType": "fact",
      "claimIds": [
        "claim:demo-ride-2026-07-22:v2:climb.representativeClimbCount",
        "claim:demo-ride-2026-07-22:v2:segment.climb.event-climb-84688-88849.averageGrade",
        "claim:demo-ride-2026-07-22:v2:segment.climb.event-climb-84688-88849.power.mean"
      ]
    },
    {
      "text": "10 秒峰值平均功率达到 566W，20 秒峰值平均功率 538W，30 秒峰值平均功率 516W。",
      "conclusionType": "fact",
      "claimIds": [
        "claim:demo-ride-2026-07-22:v2:power.peakAverage.10s",
        "claim:demo-ride-2026-07-22:v2:power.peakAverage.20s",
        "claim:demo-ride-2026-07-22:v2:power.peakAverage.30s"
      ]
    }
  ],
  "dimensions": [
    {
      "dimensionId": "pacingExecution",
      "assertions": [
        {
          "text": "本次骑行移动时长 6 小时 40 分钟，总用时 7 小时 2 分钟，途中停车 14 次。",
          "conclusionType": "fact",
          "claimIds": [
            "claim:demo-ride-2026-07-22:v2:timing.movingDurationS",
            "claim:demo-ride-2026-07-22:v2:metric.elapsedDurationS",
            "claim:demo-ride-2026-07-22:v2:stops.count"
          ]
        },
        {
          "text": "平均速度 24.06 km/h，速度变异系数 49.2%，速度波动较大。",
          "conclusionType": "fact",
          "claimIds": [
            "claim:demo-ride-2026-07-22:v2:speed.mean",
            "claim:demo-ride-2026-07-22:v2:speed.coefficientOfVariation"
          ]
        },
        {
          "text": "巡航段平均速度 29.33 km/h，平均功率 143W；另一巡航段平均速度 26.7 km/h，平均功率 137W。",
          "conclusionType": "fact",
          "claimIds": [
            "claim:demo-ride-2026-07-22:v2:segment.cruise.cruise-0-23950.speed.mean",
            "claim:demo-ride-2026-07-22:v2:segment.cruise.cruise-0-23950.power.mean",
            "claim:demo-ride-2026-07-22:v2:segment.cruise.cruise-1-24179.speed.mean",
            "claim:demo-ride-2026-07-22:v2:segment.cruise.cruise-1-24179.power.mean"
          ]
        },
        {
          "text": "地形分类覆盖率为 100%，其中爬坡段 24 个、平路段 41 个、下坡段 22 个。",
          "conclusionType": "fact",
          "claimIds": [
            "claim:demo-ride-2026-07-22:v2:terrain.classifiedCoverageRatio",
            "claim:demo-ride-2026-07-22:v2:terrain.climbRunCount",
            "claim:demo-ride-2026-07-22:v2:terrain.flatRunCount",
            "claim:demo-ride-2026-07-22:v2:terrain.descentRunCount"
          ]
        }
      ]
    },
    {
      "dimensionId": "climbPerformance",
      "assertions": [
        {
          "text": "本次骑行累计爬升 2924 米，累计下降 2808 米，爬坡段总距离 70.2 公里，平路 16.1 公里，下坡 73.3 公里。",
          "conclusionType": "fact",
          "claimIds": [
            "claim:demo-ride-2026-07-22:v2:metric.elevationGainM",
            "claim:demo-ride-2026-07-22:v2:metric.elevationLossM",
            "claim:demo-ride-2026-07-22:v2:terrain.trendClimbDistanceM",
            "claim:demo-ride-2026-07-22:v2:terrain.trendFlatDistanceM",
            "claim:demo-ride-2026-07-22:v2:terrain.trendDescentDistanceM"
          ]
        },
        {
          "text": "最具挑战的爬坡段平均坡度 11.1%，距离 4.2 公里，用时 25 分钟，平均功率 256W，平均速度 9.9 km/h。",
          "conclusionType": "fact",
          "claimIds": [
            "claim:demo-ride-2026-07-22:v2:segment.climb.event-climb-84688-88849.averageGrade",
            "claim:demo-ride-2026-07-22:v2:segment.climb.event-climb-84688-88849.distanceM",
            "claim:demo-ride-2026-07-22:v2:segment.climb.event-climb-84688-88849.span",
            "claim:demo-ride-2026-07-22:v2:segment.climb.event-climb-84688-88849.power.mean",
            "claim:demo-ride-2026-07-22:v2:segment.climb.event-climb-84688-88849.speed.mean"
          ]
        },
        {
          "text": "另一个爬坡段平均坡度 5.7%，距离 8.1 公里，用时 38 分钟，平均功率 185W，平均速度 13.26 km/h。",
          "conclusionType": "fact",
          "claimIds": [
            "claim:demo-ride-2026-07-22:v2:segment.climb.event-climb-37936-46050.averageGrade",
            "claim:demo-ride-2026-07-22:v2:segment.climb.event-climb-37936-46050.distanceM",
            "claim:demo-ride-2026-07-22:v2:segment.climb.event-climb-37936-46050.span",
            "claim:demo-ride-2026-07-22:v2:segment.climb.event-climb-37936-46050.power.mean",
            "claim:demo-ride-2026-07-22:v2:segment.climb.event-climb-37936-46050.speed.mean"
          ]
        },
        {
          "text": "第三个爬坡段平均坡度 4.9%，距离 5.6 公里，用时 22 分钟，平均功率 206W，平均速度 16.98 km/h。",
          "conclusionType": "fact",
          "claimIds": [
            "claim:demo-ride-2026-07-22:v2:segment.climb.event-climb-110427-115991.averageGrade",
            "claim:demo-ride-2026-07-22:v2:segment.climb.event-climb-110427-115991.distanceM",
            "claim:demo-ride-2026-07-22:v2:segment.climb.event-climb-110427-115991.span",
            "claim:demo-ride-2026-07-22:v2:segment.climb.event-climb-110427-115991.power.mean",
            "claim:demo-ride-2026-07-22:v2:segment.climb.event-climb-110427-115991.speed.mean"
          ]
        },
        {
          "text": "本次骑行共识别出 15 个爬坡段，其中 3 个最具代表性的爬坡段难度评分分别为 268、509 和 131。",
          "conclusionType": "fact",
          "claimIds": [
            "claim:demo-ride-2026-07-22:v2:climb.representativeClimbCount",
            "claim:demo-ride-2026-07-22:v2:segment.climb.event-climb-37936-46050.difficultyScore",
            "claim:demo-ride-2026-07-22:v2:segment.climb.event-climb-84688-88849.difficultyScore",
            "claim:demo-ride-2026-07-22:v2:segment.climb.event-climb-110427-115991.difficultyScore"
          ]
        }
      ]
    },
    {
      "dimensionId": "powerOutput",
      "assertions": [
        {
          "text": "平均功率 151W，归一化功率 197W，平均功率体重比 2.15 W/kg，归一化功率体重比 2.82 W/kg。",
          "conclusionType": "fact",
          "claimIds": [
            "claim:demo-ride-2026-07-22:v2:power.mean",
            "claim:demo-ride-2026-07-22:v2:power.normalizedW",
            "claim:demo-ride-2026-07-22:v2:power.averageWkg",
            "claim:demo-ride-2026-07-22:v2:power.normalizedWkg"
          ]
        },
        {
          "text": "功率变异系数 66.1%，功率波动较大；功率前后段差值 -31.5W，后段功率低于前段。",
          "conclusionType": "fact",
          "claimIds": [
            "claim:demo-ride-2026-07-22:v2:power.coefficientOfVariation",
            "claim:demo-ride-2026-07-22:v2:power.lastMinusFirst"
          ]
        },
        {
          "text": "高强度区间（Z5-Z7）合计占比 24%，其中 Z1 占 27%，Z2 占 14%，Z3 占 18%，Z4 占 17%，Z5 占 10%，Z6 占 9%，Z7 占 5%。",
          "conclusionType": "fact",
          "claimIds": [
            "claim:demo-ride-2026-07-22:v2:power.zone.highIntensityCombined",
            "claim:demo-ride-2026-07-22:v2:power.zone.z1",
            "claim:demo-ride-2026-07-22:v2:power.zone.z2",
            "claim:demo-ride-2026-07-22:v2:power.zone.z3",
            "claim:demo-ride-2026-07-22:v2:power.zone.z4",
            "claim:demo-ride-2026-07-22:v2:power.zone.z5",
            "claim:demo-ride-2026-07-22:v2:power.zone.z6",
            "claim:demo-ride-2026-07-22:v2:power.zone.z7"
          ]
        },
        {
          "text": "功率与速度在同一时间窗口内的覆盖率为 99%，代表性窗口的覆盖率分别为 100%、100% 和 77%。",
          "conclusionType": "fact",
          "claimIds": [
            "claim:demo-ride-2026-07-22:v2:relation.fixed.power-speed.aggregate",
            "claim:demo-ride-2026-07-22:v2:relation.fixed.power-speed.rep.2",
            "claim:demo-ride-2026-07-22:v2:relation.fixed.power-speed.rep.3",
            "claim:demo-ride-2026-07-22:v2:relation.fixed.power-speed.rep.159"
          ]
        },
        {
          "text": "整体功率输出水平较高，但波动明显，且后段功率有所下降，可能反映了长距离骑行中的疲劳积累。",
          "conclusionType": "interpretation",
          "claimIds": [
            "claim:demo-ride-2026-07-22:v2:power.mean",
            "claim:demo-ride-2026-07-22:v2:power.coefficientOfVariation",
            "claim:demo-ride-2026-07-22:v2:power.lastMinusFirst"
          ]
        }
      ]
    },
    {
      "dimensionId": "intensityAndTrainingLoad",
      "assertions": [
        {
          "text": "本次骑行训练压力指数（TSS）为 640.2，强度因子 0.99，活动消耗 4439 千卡。",
          "conclusionType": "fact",
          "claimIds": [
            "claim:demo-ride-2026-07-22:v2:power.trainingStressScore",
            "claim:demo-ride-2026-07-22:v2:power.intensityFactor",
            "claim:demo-ride-2026-07-22:v2:metric.activityEnergyKcal"
          ]
        },
        {
          "text": "基于验证 FTP 200W，本次骑行强度因子接近 1.0，属于高强度训练负荷。",
          "conclusionType": "interpretation",
          "claimIds": [
            "claim:demo-ride-2026-07-22:v2:profile.verifiedFtpW",
            "claim:demo-ride-2026-07-22:v2:power.intensityFactor"
          ]
        }
      ]
    },
    {
      "dimensionId": "cadenceStrategy",
      "assertions": [
        {
          "text": "平均踏频 76 rpm，但该数据部分缺失，可信度有限。",
          "conclusionType": "fact",
          "claimIds": ["claim:demo-ride-2026-07-22:v2:cadence.mean"]
        },
        {
          "text": "踏频分布中，耐力区间占 44%，稳定区间占 37%，低区间占 7%，高区间占 11%，极高区间占 0%。",
          "conclusionType": "fact",
          "claimIds": [
            "claim:demo-ride-2026-07-22:v2:cadence.zone.endurance",
            "claim:demo-ride-2026-07-22:v2:cadence.zone.steady",
            "claim:demo-ride-2026-07-22:v2:cadence.zone.low",
            "claim:demo-ride-2026-07-22:v2:cadence.zone.high",
            "claim:demo-ride-2026-07-22:v2:cadence.zone.very-high"
          ]
        },
        {
          "text": "踏频变异系数 15.3%，前后段差值 -2.9 rpm，踏频整体较为稳定。",
          "conclusionType": "fact",
          "claimIds": [
            "claim:demo-ride-2026-07-22:v2:cadence.coefficientOfVariation",
            "claim:demo-ride-2026-07-22:v2:cadence.lastMinusFirst"
          ]
        }
      ]
    },
    {
      "dimensionId": "crossSensorCoordination",
      "assertions": [
        {
          "text": "功率与速度在同一时间窗口内的覆盖率平均为 99%，最低代表性窗口覆盖率为 77%。",
          "conclusionType": "fact",
          "claimIds": [
            "claim:demo-ride-2026-07-22:v2:relation.fixed.power-speed.aggregate",
            "claim:demo-ride-2026-07-22:v2:relation.fixed.power-speed.rep.159"
          ]
        }
      ]
    }
  ],
  "suggestions": [
    {
      "text": "鉴于本次骑行高强度区间占比较高，建议后续安排低强度恢复骑行，并注意补充水分和营养。",
      "conclusionType": "suggestion",
      "claimIds": ["claim:demo-ride-2026-07-22:v2:power.zone.highIntensityCombined"],
      "riskNote": "恢复建议基于单次骑行负荷，不构成恢复状态评估。"
    },
    {
      "text": "下次骑行可尝试在爬坡段保持更均匀的功率输出，以减少功率波动。",
      "conclusionType": "suggestion",
      "claimIds": ["claim:demo-ride-2026-07-22:v2:power.coefficientOfVariation"],
      "riskNote": "功率波动受地形影响，建议结合具体路段分析。"
    }
  ],
  "limitations": [
    "terrain.climbRunCount:AGGREGATED_FROM_24_WINDOWS",
    "terrain.flatRunCount:AGGREGATED_FROM_41_WINDOWS",
    "terrain.descentRunCount:AGGREGATED_FROM_22_WINDOWS",
    "heartRate:SERIES_MISSING",
    "climb.representativeClimbCount:AGGREGATED_FROM_15_WINDOWS",
    "relation.fixed.power-speed.aggregate:AGGREGATED_FROM_776_WINDOWS"
  ]
}
